/* ===================== BÀI 19 · Tìm kiếm và thống kê dãy ===================== */
/* Bài 19 · Tìm kiếm và thống kê dãy (AMTS-EMB-002-M05-L03, X86-019) — sinh bởi tools/author/mpu8086/l19.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P19=[{"label": "Ví dụ: tổng mảng word, SI tăng 2", "code": "; Ví dụ 1: tổng một mảng word, SI tăng 2 mỗi phần tử\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nmang    DW      120, 340, 5, 1000, 35\ntong    DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     SI, OFFSET mang\n        MOV     CX, 5                   ; số phần tử\n        XOR     AX, AX                  ; tổng\ncong:\n        ADD     AX, [SI]                ; phần tử word tại DS:SI\n        ADD     SI, 2                   ; word: 2 byte mỗi phần tử\n        LOOP    cong\n        MOV     tong, AX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Mảng 5 word: 120 + 340 + 5 + 1000 + 35 = 1500 = 05DCh (tong: DC 05, little-endian). Con trỏ SI tăng 2 mỗi vòng; ADD AX, [SI] tốn 9 + 5 = 14 chu kỳ. Xem phần Bộ nhớ: mỗi phần tử chiếm 2 ô. Đoán trước: sau vòng thứ hai, AX bằng bao nhiêu (hệ 10)? Đáp án 460."}, {"label": "Ví dụ: lớn nhất có dấu và vị trí đầu tiên", "code": "; Ví dụ 2: số lớn nhất (có dấu) và vị trí đầu tiên của nó\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nmang    DB      12, -7, 45, 3, -20, 45, 8\nlon     DB      ?\nvitri   DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     BL, mang                ; lớn nhất tạm = phần tử 0\n        MOV     BH, 0                   ; vị trí của nó\n        MOV     SI, 1\n        MOV     CX, 6                   ; còn 6 phần tử\nxet:\n        MOV     AL, mang[SI]\n        CMP     AL, BL\n        JLE     bo                      ; có dấu; <= giữ lần xuất hiện đầu\n        MOV     BL, AL\n        MOV     AX, SI\n        MOV     BH, AL                  ; vị trí mới\nbo:\n        INC     SI\n        LOOP    xet\n        MOV     lon, BL\n        MOV     vitri, BH\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lớn nhất có dấu của 12, −7, 45, 3, −20, 45, 8. Phần tử đầu làm giá trị tạm; JLE bỏ qua cả khi bằng nên 45 thứ hai (chỉ số 5) không thay vị trí: lon = 2Dh = 45, vitri = 2. Thử đổi JLE thành JL: vitri thành 5. Đoán trước: với phần tử −7, JLE có nhảy không? Đáp án: có."}, {"label": "Lỗi: tìm lớn nhất có dấu bằng JBE", "code": "; Ví dụ 3: lớn nhất của nhiệt độ có dấu (CÓ LỖI)\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nnhiet   DB      -1, 5, -12, 3           ; độ C, có dấu\nlon     DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     BL, nhiet               ; BL = -1 = FFh\n        MOV     SI, 1\n        MOV     CX, 3\nxet:\n        MOV     AL, nhiet[SI]\n        CMP     AL, BL\n        JBE     bo                      ; LỖI: không dấu, FFh = 255 thắng mọi số\n        MOV     BL, AL                  ; (sửa: JLE)\nbo:\n        INC     SI\n        LOOP    xet\n        MOV     lon, BL                 ; lon = FFh = -1, sai (đúng là 5)\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: nhiệt độ −1, 5, −12, 3 là số có dấu nhưng so bằng JBE (không dấu). Giá trị tạm −1 = FFh = 255 lớn hơn mọi byte không dấu nên không bao giờ bị thay: lon = FFh (−1), đúng ra là 5. Sửa: JBE → JLE. Đoán trước: với phần tử 5, JBE có nhảy không? Đáp án: có (5 ≤ 255)."}, {"label": "Ví dụ: nhỏ nhất và lớn nhất trong một lượt", "code": "; Ví dụ 4: nhỏ nhất và lớn nhất trong một lượt duyệt\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ndiem    DB      7, 9, 4, 10, 6, 8\nnho     DB      ?\nlon     DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     SI, OFFSET diem\n        MOV     BL, [SI]                ; nhỏ nhất tạm\n        MOV     BH, BL                  ; lớn nhất tạm\n        MOV     CX, 5\nxet:\n        INC     SI\n        MOV     AL, [SI]\n        CMP     AL, BL\n        JAE     chua_nho                ; không dấu: AL >= BL\n        MOV     BL, AL\nchua_nho:\n        CMP     AL, BH\n        JBE     chua_lon                ; AL <= BH\n        MOV     BH, AL\nchua_lon:\n        LOOP    xet\n        MOV     nho, BL\n        MOV     lon, BH\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Một lượt duyệt cho cả nhỏ nhất và lớn nhất của điểm 7, 9, 4, 10, 6, 8 (không dấu: JAE, JBE). BL giữ nhỏ nhất, BH giữ lớn nhất; nho = 4, lon = 10. Đọc mỗi phần tử một lần bằng MOV AL, [SI] (13 chu kỳ). Đoán trước: với phần tử 4, JAE có nhảy không? Đáp án: không (4 < 7 là nhỏ nhất mới)."}, {"label": "Ví dụ: đếm điểm đạt và chưa đạt", "code": "; Ví dụ 5: đếm số điểm đạt (>= 5) và chưa đạt\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ndiem    DB      7, 3, 9, 4, 10, 5, 2, 8\ndat     DB      ?\nchua    DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     SI, OFFSET diem\n        MOV     CX, 8\n        XOR     BX, BX                  ; BL = đạt, BH = chưa đạt\nxet:\n        CMP     BYTE PTR [SI], 5\n        JB      duoi\n        INC     BL\n        JMP     tiep\nduoi:\n        INC     BH\ntiep:\n        INC     SI\n        LOOP    xet\n        MOV     dat, BL\n        MOV     chua, BH\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Hai bộ đếm trong BL (đạt, ≥ 5) và BH (chưa đạt). Nhánh đạt cần JMP tiep để không chạy vào INC BH. CMP BYTE PTR [SI], 5 cần BYTE PTR vì [SI] không cho biết kích thước. dat = 5, chua = 3. Đoán trước: với điểm 5, JB có nhảy không? Đáp án: không (5 không nhỏ hơn 5)."}, {"label": "Ví dụ: tìm một word, thoát vòng khi thấy", "code": "; Ví dụ 6: tìm một word trong mảng, dừng ngay khi thấy\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nmang    DW      1200, 35, 4096, 777, 35\ntim     DW      4096\nchi     DB      0FFH                    ; chỉ số tìm được, FFh: không có\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, tim\n        MOV     SI, OFFSET mang\n        MOV     CX, 5\nso:\n        CMP     [SI], AX\n        JE      thay                    ; thấy: thoát vòng ngay\n        ADD     SI, 2\n        LOOP    so\n        JMP     het                     ; hết mảng, không thấy\nthay:\n        MOV     AX, 5                   ; JE thoát trước LOOP nên CX chưa giảm:\n        SUB     AX, CX                  ; chỉ số = 5 - CX\n        MOV     chi, AL\nhet:\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Tìm 4096 trong mảng word. JE thay thoát vòng ngay ở phần tử thứ ba (chỉ số 2), CX lúc đó = 3 nên chỉ số = 5 − CX = 2. Nếu không thấy, LOOP chạy hết rồi JMP het nhảy qua đoạn ghi chỉ số, chi giữ FFh. Đoán trước: ở phần tử thứ ba, JE có nhảy không? Đáp án: có."}, {"label": "Lỗi: mảng word mà SI chỉ tăng 1", "code": "; Ví dụ 7: mảng word mà SI chỉ tăng 1 (CÓ LỖI)\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nmang    DW      1, 2, 3                 ; byte: 01 00 02 00 03 00\ntong    DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     SI, OFFSET mang\n        MOV     CX, 3\n        XOR     AX, AX\ncong:\n        ADD     AX, [SI]\n        INC     SI                      ; LỖI: word dài 2 byte (sửa: ADD SI, 2)\n        LOOP    cong\n        MOV     tong, AX                ; 0001h + 0200h + 0002h = 0203h\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: mảng word nhưng INC SI. Ba lần đọc ở byte 0, 1, 2 của 01 00 02 00 03 00 cho 0001h, 0200h, 0002h, tổng 0203h thay vì 6. Lần đọc ở địa chỉ lẻ tốn 18 chu kỳ thay vì 14 (cột chu kỳ). Sửa: ADD SI, 2. Đoán trước: ở vòng thứ hai, ADD AX, [SI] cộng word bằng bao nhiêu (hệ 16)? Đáp án 0200h."}, {"label": "Ví dụ: đếm số âm không cần lệnh nhảy", "code": "; Ví dụ 8: đếm số âm không dùng lệnh nhảy\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nmang    DB      12, -7, 45, 3, -20, 45, 8\nam      DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     SI, OFFSET mang\n        MOV     CX, 7\n        XOR     BL, BL\nxet:\n        MOV     AL, [SI]\n        SHL     AL, 1                   ; bit dấu -> CF\n        ADC     BL, 0                   ; BL = BL + CF\n        INC     SI\n        LOOP    xet\n        MOV     am, BL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Đếm số âm không cần lệnh nhảy: SHL AL, 1 đẩy bit dấu ra CF, ADC BL, 0 cộng CF vào bộ đếm. Mọi phần tử tốn đúng 38 chu kỳ. −7 và −20 là âm: am = 2. Đoán trước: với phần tử −7 (F9h), sau SHL AL, 1, CF bằng bao nhiêu? Đáp án 1."}];
const sim19=makeX86Sim(document.getElementById("x86-l19"),{id:"s19",presets:P19,file:"BAI19.ASM"});
makeX86Ex(document.getElementById("ex-l19"),sim19,[{"t": "Lớn nhất và nhỏ nhất", "d": "Code mẫu đọc 6 phím chữ số vào mảng mang (giá trị 0–9, mỗi phần tử 1 byte). Viết tiếp để ghi số lớn nhất vào biến lon và số nhỏ nhất vào biến nho. Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 1: lớn nhất và nhỏ nhất của 6 chữ số\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nmang    DB      6 DUP(?)                ; 6 chữ số 0..9\nlon     DB      ?\nnho     DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     CX, 6\n        MOV     SI, 0\ndoc:                                    ; đọc 6 phím chữ số vào mang\n        MOV     AH, 08H\n        INT     21H\n        SUB     AL, '0'\n        MOV     mang[SI], AL\n        INC     SI\n        LOOP    doc\n; Viết tiếp: ghi số lớn nhất vào lon, nhỏ nhất vào nho.\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "385162", "mem": [{"at": "lon", "bytes": [8]}, {"at": "nho", "bytes": [1]}]}, {"in": "000000", "mem": [{"at": "lon", "bytes": [0]}, {"at": "nho", "bytes": [0]}]}, {"in": "987654", "mem": [{"at": "lon", "bytes": [9]}, {"at": "nho", "bytes": [4]}]}, {"in": "123459", "mem": [{"at": "lon", "bytes": [9]}, {"at": "nho", "bytes": [1]}]}, {"in": "505050", "mem": [{"at": "lon", "bytes": [5]}, {"at": "nho", "bytes": [0]}]}, {"in": "471039", "mem": [{"at": "lon", "bytes": [9]}, {"at": "nho", "bytes": [0]}]}]}, {"t": "Dãy có tăng ngặt không", "d": "Code mẫu đọc 6 phím chữ số vào mảng mang. Tìm chỉ số i nhỏ nhất (1–5) có mang[i] ≤ mang[i − 1]. Có thì ghi i vào biến vitri và in 'N'; không có (dãy tăng ngặt) thì giữ vitri = FFh và in 'Y'. Dừng duyệt ngay khi gặp vị trí đầu tiên. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 2: dãy 6 chữ số có tăng ngặt không\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nmang    DB      6 DUP(?)\nvitri   DB      0FFH                    ; chỉ số đầu tiên làm dãy không tăng\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     CX, 6\n        MOV     SI, 0\ndoc:                                    ; đọc 6 phím chữ số vào mang\n        MOV     AH, 08H\n        INT     21H\n        SUB     AL, '0'\n        MOV     mang[SI], AL\n        INC     SI\n        LOOP    doc\n; Viết tiếp: tìm chỉ số i nhỏ nhất (1..5) có mang[i] <= mang[i-1].\n; Có: vitri = i, in 'N'. Không có: giữ vitri = FFh, in 'Y'.\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "123456", "out": "Y", "mem": [{"at": "vitri", "bytes": [255]}]}, {"in": "124356", "out": "N", "mem": [{"at": "vitri", "bytes": [3]}]}, {"in": "112345", "out": "N", "mem": [{"at": "vitri", "bytes": [1]}]}, {"in": "135799", "out": "N", "mem": [{"at": "vitri", "bytes": [5]}]}, {"in": "012389", "out": "Y", "mem": [{"at": "vitri", "bytes": [255]}]}, {"in": "987654", "out": "N", "mem": [{"at": "vitri", "bytes": [1]}]}]}, {"t": "Đếm phần tử lớn hơn k nhanh hơn", "d": "Mảng diem (16 byte, giá trị 0–10) có sẵn. Đọc một phím chữ số k bằng INT 21h hàm 08h và ghi vào biến dem số phần tử của diem lớn hơn k. Code mẫu đã đúng nhưng chậm. Viết lại để đạt cả giới hạn chu kỳ và giới hạn byte mã. Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 3: đếm số điểm lớn hơn k (k là phím 0..9)\n; Bản này đúng nhưng chậm: diem[BX], INC dem, DEC CX/JNZ\n; và một lệnh nhảy mỗi phần tử. Hãy viết lại.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ndiem    DB      7, 3, 10, 5, 8, 0, 9, 6, 4, 10, 2, 7, 5, 9, 1, 8\ndem     DB      ?                       ; số phần tử lớn hơn k\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H\n        INT     21H\n        SUB     AL, '0'                 ; AL = k (0..9)\n        MOV     dem, 0\n        MOV     BX, 0\n        MOV     CX, 16\nxet:\n        CMP     diem[BX], AL\n        JBE     bo                      ; diem <= k: không đếm\n        INC     dem\nbo:\n        INC     BX\n        DEC     CX\n        JNZ     xet\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "0", "mem": [{"at": "dem", "bytes": [15]}]}, {"in": "5", "mem": [{"at": "dem", "bytes": [9]}]}, {"in": "9", "mem": [{"at": "dem", "bytes": [2]}]}, {"in": "7", "mem": [{"at": "dem", "bytes": [6]}]}, {"in": "3", "mem": [{"at": "dem", "bytes": [12]}]}, {"in": "1", "mem": [{"at": "dem", "bytes": [14]}]}], "perf": {"cycles": 780, "bytes": 38}}]);

makeQuiz("quiz19","score19",[{"q": "Mảng khai báo <code>mang DW 10 DUP(?)<\/code>, duyệt bằng <code>ADD AX, [SI]<\/code>. Sau mỗi phần tử phải làm gì với SI?", "o": ["<code>ADD SI, 2<\/code>", "<code>INC SI<\/code>", "<code>ADD SI, 4<\/code>", "Không cần, LOOP tự tăng SI"], "a": 0, "e": "Mỗi word chiếm 2 byte. INC SI đọc lệch nửa word (Ví dụ 7); LOOP chỉ giảm CX, không đụng SI."}, {"q": "Tìm lớn nhất có dấu, khởi tạo <code>MOV BL, 0<\/code> thay vì phần tử đầu. Mảng nào cho kết quả <b>sai<\/b>?", "o": ["5, 0, 7", "0, 0, 0", "−3, −8, −1", "−2, 4, −9"], "a": 2, "e": "Mọi phần tử của −3, −8, −1 đều nhỏ hơn 0 nên BL giữ 0, trong khi lớn nhất đúng là −1. Ba mảng còn lại có lớn nhất ≥ 0 nên kết quả trùng."}, {"q": "<code>mang DB 3, 9, 9, 2<\/code>; tìm lớn nhất bắt đầu với BL = 3, vt = 0, mỗi phần tử: <code>CMP AL, BL<\/code> / <code>JL bo<\/code> rồi cập nhật BL và vt. Cuối cùng vt bằng bao nhiêu?", "o": ["1", "3", "0", "2"], "a": 3, "e": "JL chỉ bỏ qua khi nhỏ hơn hẳn, nên khi bằng (9 thứ hai) vẫn cập nhật: vt = 2, vị trí cuối cùng của 9. Muốn vị trí đầu (1) dùng JLE."}, {"q": "Cặp lệnh nào đếm đúng số phần tử <b>lẻ<\/b> (AL là phần tử, BL là bộ đếm)?", "o": ["<code>SHL AL, 1<\/code> / <code>ADC BL, 0<\/code>", "<code>TEST AL, 1<\/code> / <code>ADC BL, 0<\/code>", "<code>SHR AL, 1<\/code> / <code>ADC BL, 0<\/code>", "<code>CMP AL, 1<\/code> / <code>ADC BL, 0<\/code>"], "a": 2, "e": "SHR đưa bit 0 ra CF (1 khi lẻ). SHL đưa bit 7 (đếm số âm). TEST luôn xóa CF nên đếm 0. CMP AL, 1 cho CF = 1 khi AL < 1, tức đếm số 0."}, {"q": "Tìm kiếm thoát bằng <code>JE thay<\/code> đặt trước <code>LOOP<\/code>, CX ban đầu = 8. Thấy ở phần tử chỉ số 3 (đếm từ 0). Lúc nhảy tới <code>thay<\/code>, CX bằng bao nhiêu?", "o": ["4", "5", "3", "8"], "a": 1, "e": "Ba phần tử 0, 1, 2 không khớp, mỗi phần tử một lần LOOP: 8 → 7 → 6 → 5. Ở phần tử 3, JE nhảy trước LOOP nên CX vẫn là 5 = 8 − 3."}]);

